insert into public.activities (id, module, title, summary, duration_min, requires_standing, needs) values
  ('pos-intencion-jornada', 'positive', 'Empezar la jornada con intención',
insert into public.activity_steps (activity_id, position, text, seconds, animation, pose) values
  ('reset-desconexion', 1, 'Bloquea la pantalla y deja el móvil boca abajo.', 45, 'still', 'respirar'),
  ('reset-desconexion', 2, 'Si puedes, ve a otro espacio: una ventana, la cocina, el exterior.', 90, 'move', 'de-pie-caminar'),
  ('reset-desconexion', 3, 'Elige un punto cerca de ti y fíjate en él con todo detalle: su color, su forma, su textura.', 75, 'eyes', 'mirar-lejos'),
  ('reset-desconexion', 4, 'Bebe agua o prepárate una infusión con calma.', 120, 'still', 'beber'),
  ('reset-desconexion', 5, 'Lleva los brazos hacia el techo y entrelaza los dedos.', 20, 'move', 'brazos-arriba'),
  ('reset-desconexion', 6, 'Sigue la voz y el cuenco: inspira mientras te estiras un poco más y suelta el aire relajando los hombros.', 60, 'breath:4-6', 'brazos-arriba'),
  ('reset-desconexion', 7, 'Cierra los ojos y escucha. Busca el sonido más lejano que puedas oír y quédate con él.', 130, 'pulse', 'escuchar'),
  ('reset-desconexion', 8, 'Vuelve poco a poco a tu sitio.', 60, 'still', 'respirar'),
  ('breathe-consciente', 1, 'Ponte cómodo y, si quieres, cierra los ojos o baja la mirada.', 20, 'still', 'respirar'),
  ('breathe-consciente', 2, 'Respira con normalidad. Nota el aire fresco al entrar por la nariz y algo más cálido al salir.', 40, 'still', 'respirar'),
  ('breathe-consciente', 3, 'Sigue los sonidos: inspira con el tono que sube y suelta el aire con el tono que baja. El cuenco marca cada segundo.', 120, 'breath:4-6', 'respirar'),
  ('breathe-consciente', 4, 'Si te distraes, no pasa nada. Vuelve al sonido de tu respiración.', 60, 'breath:4-6', 'respirar'),
  ('breathe-consciente', 5, 'Deja que la respiración recupere su ritmo natural.', 40, 'still', 'respirar'),
  ('breathe-consciente', 6, 'Abre los ojos poco a poco y vuelve a lo que estabas haciendo.', 20, 'still', 'respirar'),
  ('breathe-soltar-tension', 1, 'Apoya la espalda y deja las manos sobre las piernas.', 20, 'still', 'respirar'),
  ('breathe-soltar-tension', 2, 'Inspira por la nariz en 4 tiempos y suelta el aire por la boca en 8, despacio.', 100, 'breath:4-8', 'respirar'),
  ('breathe-soltar-tension', 3, 'Con cada exhalación, imagina que te derrites como una vela: los hombros, la mandíbula y las manos se vuelven blandos.', 100, 'breath:4-8', 'respirar'),
  ('breathe-soltar-tension', 4, 'Vuelve a una respiración tranquila, sin contar.', 50, 'still', 'respirar'),
  ('breathe-soltar-tension', 5, 'Nota qué sensación tienes ahora en el cuerpo. Cuando quieras, sigue con tu día.', 30, 'still', 'respirar'),
  ('pos-gratitud', 1, 'Vamos a dedicar cinco minutos a fijarnos en lo que sí va bien. Ponte cómodo y respira con calma.', 30, 'breath:4-6', 'respirar'),
  ('pos-gratitud', 2, 'Piensa en algo que haya ido bien hoy, aunque sea pequeño: has llegado a tiempo, no había tráfico, el café estaba rico…', 70, 'pulse', 'mano-corazon'),
  ('pos-gratitud', 3, 'Ahora piensa en una persona a la que tú hayas ayudado últimamente. ¿Cómo te sentiste?', 70, 'pulse', 'mano-corazon'),
  ('pos-gratitud', 4, 'Agradece cualquier cosa, lo primero que te venga a la mente.', 60, 'pulse', 'mano-corazon'),
  ('pos-gratitud', 5, 'Elige una de esas tres cosas y sonríe al recordarla. Nota cómo cambia tu cara… y tu ánimo.', 40, 'still', 'respirar'),
  ('pos-gratitud', 6, 'Si te apetece, da las gracias a alguien hoy.', 30, 'still', 'respirar'),
  ('mind-recorrido-cuerpo', 1, 'Cierra los ojos o baja la mirada. Haz una respiración completa: llena el abdomen, luego el pecho… y suelta despacio.', 45, 'breath:4-6', 'respirar'),
  ('mind-recorrido-cuerpo', 2, 'Apoya bien los pies y presiona un poco el suelo. Imagina una luz cálida que entra por las puntas de tus pies.', 60, 'still', 'respirar'),
  ('mind-recorrido-cuerpo', 3, 'La luz sube por los tobillos hacia las piernas y las rodillas. Deja que se aflojen.', 60, 'still', 'respirar'),
  ('mind-recorrido-cuerpo', 4, 'Nota tus muslos sobre la silla. Lleva el peso a un lado, luego al otro, y vuelve al centro.', 60, 'move', 'peso-lados'),
  ('mind-recorrido-cuerpo', 5, 'La luz llega al estómago y al abdomen, que suben y bajan al respirar.', 60, 'breath:4-6', 'respirar'),
  ('mind-recorrido-cuerpo', 6, 'Sube al pecho y se extiende por toda la espalda. Suelta lo que sobra.', 75, 'breath:4-6', 'respirar'),
  ('mind-recorrido-cuerpo', 7, 'Ahora recorre los hombros, baja por los brazos y llega hasta las manos.', 75, 'still', 'respirar'),
  ('mind-recorrido-cuerpo', 8, 'Por último, la luz sube por el cuello hasta la cara: suaviza la frente, los ojos y la mandíbula.', 60, 'still', 'respirar'),
  ('mind-recorrido-cuerpo', 9, 'Siente tu cuerpo entero lleno de luz, respirando.', 60, 'breath:4-6', 'respirar'),
  ('mind-recorrido-cuerpo', 10, 'Mueve suavemente los dedos y, cuando quieras, abre los ojos.', 45, 'still', 'respirar'),
  ('pos-cerrar-jornada', 1, 'Aparta la vista de la pantalla y respira hondo.', 30, 'breath:4-6', 'respirar'),
  ('pos-cerrar-jornada', 2, 'Recuerda una cosa que has hecho hoy y de la que te alegras.', 60, 'pulse', 'mano-corazon'),
  ('pos-cerrar-jornada', 3, 'Imagina una caja delante de ti. Deja dentro las preocupaciones de hoy, una a una.', 60, 'pulse', 'guardar'),
  ('pos-cerrar-jornada', 4, 'Guarda también en tu caja todo lo que tengas que hacer mañana. Ahí está a salvo.', 50, 'pulse', 'guardar'),
  ('pos-cerrar-jornada', 5, 'Ciérrala con llave y métela en tu mochila.', 40, 'still', 'guardar'),
  ('pos-cerrar-jornada', 6, 'Di para ti: «Por hoy, es suficiente».', 30, 'still', 'mano-corazon'),
  ('pos-cerrar-jornada', 7, 'Respira y cierra la jornada.', 30, 'breath:4-6', 'respirar'),
  ('stretch-espalda-manos', 1, 'Siéntate en el borde de la silla, con los pies bien apoyados.', 30, 'still', 'respirar'),
  ('stretch-espalda-manos', 2, 'Rota los hombros hacia atrás, despacio, dibujando círculos amplios.', 45, 'move', 'hombros-circulos'),
  ('stretch-espalda-manos', 3, 'Lleva el pecho hacia delante arqueando la espalda, y luego redondéala hacia atrás. Alterna despacio.', 60, 'move', 'espalda-arquear'),
  ('stretch-espalda-manos', 4, 'Gira el tronco hacia la derecha apoyando la mano en el respaldo. Mantén y respira.', 45, 'breath:4-6', 'tronco-giro-derecha'),
  ('stretch-espalda-manos', 5, 'Repite el giro hacia la izquierda.', 45, 'breath:4-6', 'tronco-giro-izquierda'),
  ('stretch-espalda-manos', 6, 'Inclínate hacia delante dejando caer los brazos hacia el suelo. Relaja la espalda.', 45, 'still', 'inclinar-delante'),
  ('stretch-espalda-manos', 7, 'Sube despacio, vértebra a vértebra, hasta quedar erguido.', 30, 'move', 'inclinar-delante'),
  ('stretch-espalda-manos', 8, 'Estira los brazos hacia el techo entrelazando los dedos.', 40, 'move', 'brazos-arriba'),
  ('stretch-espalda-manos', 9, 'Abre y cierra las manos con energía varias veces.', 40, 'move', 'manos-abrir'),
  ('stretch-espalda-manos', 10, 'Haz círculos con las muñecas en ambos sentidos.', 45, 'move', 'munecas'),
  ('stretch-espalda-manos', 11, 'Estira el brazo con la palma hacia fuera y lleva los dedos suavemente hacia ti. Cambia de mano a mitad.', 60, 'move', 'muneca-estirar'),
  ('stretch-espalda-manos', 12, 'Ahora con la palma hacia abajo, lleva los dedos hacia el suelo. Cambia de mano a mitad.', 60, 'move', 'muneca-estirar'),
  ('stretch-espalda-manos', 13, 'Sacude las manos sueltas y respira con calma.', 55, 'still', 'manos-sacudir'),
  ('pos-intencion-dia', 1, 'Haz dos respiraciones profundas.', 30, 'breath:4-6', 'respirar'),
  ('pos-intencion-dia', 2, 'Visualiza algo que te gustaría hacer hoy, algo que te haga ilusión.', 60, 'pulse', 'respirar'),
  ('pos-intencion-dia', 3, 'Hazle una foto a esa imagen y guárdala en tu memoria.', 50, 'pulse', 'foto'),
  ('pos-intencion-dia', 4, 'Repite para ti: «Hoy me doy permiso para ir a mi ritmo».', 60, 'still', 'mano-corazon'),
  ('pos-intencion-dia', 5, 'Elige un gesto pequeño para cuidarte hoy: un paseo, una llamada, una comida sin prisa.', 60, 'pulse', 'respirar'),
  ('pos-intencion-dia', 6, 'Respira y empieza.', 40, 'breath:4-6', 'respirar'),
  ('pos-intencion-jornada', 1, 'Antes de abrir el correo, haz dos respiraciones profundas.', 30, 'breath:4-6', 'respirar'),
  ('pos-intencion-jornada', 2, 'Visualiza cómo te gustaría que fuera tu jornada de hoy: con qué ritmo, con qué ánimo.', 60, 'pulse', 'respirar'),
  ('pos-intencion-jornada', 3, 'Hazle una foto a esa imagen y guárdala en tu memoria.', 40, 'pulse', 'foto'),
  ('pos-intencion-jornada', 4, 'Elige la tarea más importante de hoy. Si solo hicieras esa, ¿la jornada habría merecido la pena?', 60, 'pulse', 'respirar'),
  ('pos-intencion-jornada', 5, 'Repite para ti: «Hago primero lo importante; el resto, paso a paso».', 50, 'still', 'mano-corazon'),
  ('pos-intencion-jornada', 6, 'Decide cuándo harás tu primera pausa. Tu bienestar también forma parte de tu jornada.', 35, 'still', 'respirar'),
  ('pos-intencion-jornada', 7, 'Respira y empieza.', 25, 'breath:4-6', 'respirar');
